            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u00AB\u0422\u044B\u0441\u044F\u0447\u0435\u00BB \u043E\u0447\u043A\u0438 \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 \u0432\u0437\u044F\u0442\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u043F\u0430\u0440\u044B \u043A\u043E\u0440\u043E\u043B\u044F \u0441 \u0434\u0430\u043C\u043E\u0439. \u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043F\u0440\u043E\u0445\u043E\u0434\u044F\u0442 \u0442\u043E\u0440\u0433\u0438: \u0438\u0433\u0440\u043E\u043A\u0438 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u044E\u0442, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043E\u0447\u043A\u043E\u0432 \u043E\u0431\u044F\u0437\u0443\u044E\u0442\u0441\u044F \u0432\u0437\u044F\u0442\u044C. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432 \u0434\u043E\u043B\u0436\u0435\u043D \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435, \u0430 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u0442\u0430\u0440\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u043C\u0435\u0448\u0430\u0442\u044C \u0435\u043C\u0443 \u0438 \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0441\u0432\u043E\u0451. \u0426\u0435\u043B\u044C \u2014 \u0434\u043E\u0441\u0442\u0438\u0447\u044C 1000 \u043E\u0447\u043A\u043E\u0432.",
              "\u041E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D \u043D\u0430 \u0442\u0440\u043E\u0438\u0445. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u043A\u0430\u0440\u0442\u044B \u043E\u0442 \u0434\u0435\u0432\u044F\u0442\u043A\u0438 \u0434\u043E \u0442\u0443\u0437\u0430. \u041A\u0430\u0436\u0434\u043E\u043C\u0443 \u0440\u0430\u0437\u0434\u0430\u044E\u0442 \u0441\u0435\u043C\u044C, \u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E \u0442\u043E\u0440\u0433\u043E\u0432 \u0434\u043E\u0441\u0442\u0430\u043D\u0443\u0442\u0441\u044F \u0435\u0449\u0451 \u0442\u0440\u0438 \u043A\u0430\u0440\u0442\u044B \u043F\u0440\u0438\u043A\u0443\u043F\u0430."),
            rule_section(:cards, "\u0421\u0442\u0430\u0440\u0448\u0438\u043D\u0441\u0442\u0432\u043E \u0438 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043A\u0430\u0440\u0442",
              "\u041F\u043E\u0441\u043B\u0435 \u0442\u043E\u0440\u0433\u043E\u0432 \u0438\u0433\u0440\u043E\u043A\u0438 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043A\u043B\u0430\u0434\u0443\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435. \u0422\u0440\u0438 \u043A\u0430\u0440\u0442\u044B \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u0432\u0437\u044F\u0442\u043A\u0443; \u0437\u0430\u0431\u0440\u0430\u0432\u0448\u0438\u0439 \u0435\u0451 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0438\u0445 \u043E\u0447\u043A\u0438.",
              "\u041E\u0442 \u0441\u0442\u0430\u0440\u0448\u0435\u0439 \u043A \u043C\u043B\u0430\u0434\u0448\u0435\u0439 \u043A\u0430\u0440\u0442\u044B \u0438\u0434\u0443\u0442 \u0442\u0430\u043A: \u0442\u0443\u0437, \u0434\u0435\u0441\u044F\u0442\u043A\u0430, \u043A\u043E\u0440\u043E\u043B\u044C, \u0434\u0430\u043C\u0430, \u0432\u0430\u043B\u0435\u0442, \u0434\u0435\u0432\u044F\u0442\u043A\u0430. \u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0443 \u043D\u0438\u0445 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0430\u044F:",
              "- \u0422\u0443\u0437 \u2014 11 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0414\u0435\u0441\u044F\u0442\u043A\u0430 \u2014 10 \u043E\u0447\u043A\u043E\u0432.",
              "- \u041A\u043E\u0440\u043E\u043B\u044C \u2014 4 \u043E\u0447\u043A\u0430.",
              "- \u0414\u0430\u043C\u0430 \u2014 3 \u043E\u0447\u043A\u0430.",
              "- \u0412\u0430\u043B\u0435\u0442 \u2014 2 \u043E\u0447\u043A\u0430.",
              "- \u0414\u0435\u0432\u044F\u0442\u043A\u0430 \u2014 0 \u043E\u0447\u043A\u043E\u0432.",
              "\u0412\u0441\u044F \u043A\u043E\u043B\u043E\u0434\u0430 \u0434\u0430\u0451\u0442 120 \u043E\u0447\u043A\u043E\u0432. \u0411\u043E\u043B\u044C\u0448\u0435 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0437\u0430 \u043C\u0430\u0440\u044C\u044F\u0436 \u2014 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u0443\u044E \u043F\u0430\u0440\u0443 \u043A\u043E\u0440\u043E\u043B\u044F \u0438 \u0434\u0430\u043C\u044B \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u041A\u0430\u043A \u0435\u0451 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0442\u044C, \u043E\u043F\u0438\u0441\u0430\u043D\u043E \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \u00AB\u041C\u0430\u0440\u044C\u044F\u0436\u0438\u00BB."),
            rule_section(:auction, "\u0422\u043E\u0440\u0433\u0438",
              "\u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0440\u0443\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438\u043B\u0438 \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0435\u0451 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 H. \u041F\u0435\u0440\u0432\u044B\u043C \u0442\u043E\u0440\u0433\u0443\u0435\u0442\u0441\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u043F\u043E\u0441\u043B\u0435 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E. \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u0430\u044F \u0441\u0442\u0430\u0432\u043A\u0430 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 100, \u043A\u0430\u0436\u0434\u043E\u0435 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u2014 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 5. \u0412\u0441\u0435 \u0441\u0442\u0430\u0432\u043A\u0438 \u043A\u0440\u0430\u0442\u043D\u044B \u043F\u044F\u0442\u0438.",
              "\u0412 \u0441\u0432\u043E\u044E \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u043D\u0430 \u043B\u044E\u0431\u043E\u0439 \u043A\u0430\u0440\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u0441\u0442\u0430\u0432\u043E\u043A. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043E\u0431\u0435\u0449\u0430\u0435\u043C\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u043E\u0447\u043A\u043E\u0432 \u0438\u043B\u0438 \u043F\u0430\u0441 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0421\u043F\u0430\u0441\u043E\u0432\u0430\u0432, \u0432\u044B \u0432\u044B\u0445\u043E\u0434\u0438\u0442\u0435 \u0438\u0437 \u044D\u0442\u0438\u0445 \u0442\u043E\u0440\u0433\u043E\u0432. \u041D\u0430\u0447\u0438\u043D\u0430\u044E\u0449\u0438\u0439 \u043E\u0431\u044F\u0437\u0430\u043D \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0443.",
              "\u0411\u0435\u0437 \u043C\u0430\u0440\u044C\u044F\u0436\u0430 \u0432 \u0440\u0443\u043A\u0435 \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0431\u0435\u0449\u0430\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0435 120. \u041A\u0430\u0436\u0434\u044B\u0439 \u0438\u043C\u0435\u044E\u0449\u0438\u0439\u0441\u044F \u043C\u0430\u0440\u044C\u044F\u0436 \u043F\u043E\u0434\u043D\u0438\u043C\u0430\u0435\u0442 \u043F\u0440\u0435\u0434\u0435\u043B \u043D\u0430 \u0441\u0432\u043E\u044E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C, \u043D\u043E \u0430\u0431\u0441\u043E\u043B\u044E\u0442\u043D\u044B\u0439 \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C \u2014 400. \u0412 \u0441\u043F\u0438\u0441\u043A\u0435 \u043F\u043E\u043A\u0430\u0437\u0430\u043D\u044B \u043B\u0438\u0448\u044C \u0441\u0442\u0430\u0432\u043A\u0438, \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0435 \u0441 \u0432\u0430\u0448\u0438\u043C\u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438.",
              "\u041A\u043E\u0433\u0434\u0430 \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u043B\u0438 \u0432\u0441\u0435, \u043A\u0440\u043E\u043C\u0435 \u043E\u0434\u043D\u043E\u0433\u043E, \u0442\u043E\u0440\u0433\u0438 \u0437\u0430\u043A\u043E\u043D\u0447\u0435\u043D\u044B. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0441\u0442\u0430\u0432\u043A\u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0435\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u043C \u2014 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E\u043C \u043D\u0430 \u044D\u0442\u0443 \u0440\u0430\u0437\u0434\u0430\u0447\u0443. \u0422\u0435\u043A\u0443\u0449\u0438\u0435 \u0441\u0442\u0430\u0432\u043A\u0438 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0430 B."),
            rule_section(:talon, "\u041F\u0440\u0438\u043A\u0443\u043F \u0438 \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442",
              "\u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u0440\u0438\u043A\u0443\u043F, \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u0432\u0441\u0435\u043C. \u0417\u0430\u0442\u0435\u043C \u043E\u0442\u0434\u0430\u0451\u0442 \u043F\u043E \u043A\u0430\u0440\u0442\u0435 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443. \u0415\u0441\u043B\u0438 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u0432\u044B, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043A\u0430\u0440\u0442\u0443 \u0434\u043B\u044F \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter; \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0434\u043B\u044F \u0432\u0442\u043E\u0440\u043E\u0433\u043E. \u0422\u0435\u043F\u0435\u0440\u044C \u0443 \u0432\u0441\u0435\u0445 \u043F\u043E \u0432\u043E\u0441\u0435\u043C\u044C \u043A\u0430\u0440\u0442.",
              "\u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u043C\u0435\u043D\u0430 \u043C\u043E\u0436\u043D\u043E \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043F\u0440\u0435\u0436\u043D\u0438\u043C \u0438\u043B\u0438 \u043F\u043E\u0432\u044B\u0441\u0438\u0442\u044C. \u0414\u043B\u044F \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u044F \u043D\u0430\u0436\u043C\u0438\u0442\u0435 B, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0447\u0438\u0441\u043B\u043E \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u041D\u043E\u0432\u044B\u0439 \u043F\u0440\u0435\u0434\u0435\u043B \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u0432 \u0440\u0443\u043A\u0435 \u043C\u0430\u0440\u044C\u044F\u0436\u0435\u0439, \u043D\u043E \u0441\u043D\u0438\u0436\u0430\u0442\u044C \u043F\u0440\u0435\u0436\u043D\u0435\u0435 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435 \u0443\u0436\u0435 \u043D\u0435\u043B\u044C\u0437\u044F.",
              "\u041F\u0435\u0440\u0432\u044B\u043C \u0437\u0430\u0445\u043E\u0434\u0438\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432. \u0415\u0441\u043B\u0438 \u043F\u043E\u0432\u044B\u0448\u0430\u0442\u044C \u043D\u0435 \u0445\u043E\u0442\u0438\u0442\u0435, \u043F\u0440\u043E\u0441\u0442\u043E \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041F\u0435\u0440\u0432\u044B\u0439 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442."),
            rule_section(:play, "\u0420\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0432\u0437\u044F\u0442\u043E\u043A",
              "\u0412 \u0441\u0432\u043E\u0439 \u0445\u043E\u0434 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0415\u0441\u043B\u0438 \u0443\u0436\u0435 \u0441\u0434\u0435\u043B\u0430\u043D \u0437\u0430\u0445\u043E\u0434, \u043D\u0443\u0436\u043D\u043E \u043E\u0442\u0432\u0435\u0447\u0430\u0442\u044C \u0432 \u0435\u0433\u043E \u043C\u0430\u0441\u0442\u044C. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043D\u0430 \u0431\u0443\u0431\u043D\u0443 \u043A\u043B\u0430\u0434\u0438\u0442\u0435 \u0431\u0443\u0431\u043D\u0443, \u0435\u0441\u043B\u0438 \u043E\u043D\u0430 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C. \u041E\u0431\u0433\u043E\u043D\u044F\u0442\u044C \u0447\u0443\u0436\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u043F\u043E \u0441\u0442\u0430\u0440\u0448\u0438\u043D\u0441\u0442\u0432\u0443 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E.",
              "\u0415\u0441\u043B\u0438 \u043D\u0443\u0436\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u043D\u0435\u0442, \u0432\u044B \u043E\u0431\u044F\u0437\u0430\u043D\u044B \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u043E\u0437\u044B\u0440\u044C, \u043A\u043E\u0433\u0434\u0430 \u043E\u043D \u0435\u0441\u0442\u044C. \u041A\u043E\u0437\u044B\u0440\u043D\u0430\u044F \u043C\u0430\u0441\u0442\u044C \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043A\u043E\u0437\u044B\u0440\u044F \u0435\u0449\u0451 \u043D\u0435\u0442: \u0435\u0433\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u043C\u0430\u0440\u044C\u044F\u0436. \u0415\u0441\u043B\u0438 \u043D\u0435\u0442 \u043D\u0438 \u043C\u0430\u0441\u0442\u0438 \u0437\u0430\u0445\u043E\u0434\u0430, \u043D\u0438 \u043A\u043E\u0437\u044B\u0440\u0435\u0439, \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439\u0442\u0435 \u043B\u044E\u0431\u0443\u044E \u043A\u0430\u0440\u0442\u0443.",
              "\u0412\u0437\u044F\u0442\u043A\u0443 \u0431\u0435\u0440\u0451\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C, \u0430 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u0435\u0439 \u2014 \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043C\u0430\u0441\u0442\u0438 \u0437\u0430\u0445\u043E\u0434\u0430. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0447\u043A\u0438 \u0442\u0440\u0451\u0445 \u043A\u0430\u0440\u0442 \u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443. \u0418\u0433\u0440\u0430\u0439\u0442\u0435 \u0442\u0430\u043A, \u043F\u043E\u043A\u0430 \u0440\u0443\u043A\u0438 \u043D\u0435 \u043E\u043F\u0443\u0441\u0442\u0435\u044E\u0442.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 C \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u0430\u0440\u0442\u044B \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438, F \u2014 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C."),
            rule_section(:marriages, "\u041C\u0430\u0440\u044C\u044F\u0436\u0438",
              "\u0414\u0435\u0440\u0436\u0430 \u043A\u043E\u0440\u043E\u043B\u044F \u0438 \u0434\u0430\u043C\u0443 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438, \u043C\u043E\u0436\u043D\u043E \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u043C\u0430\u0440\u044C\u044F\u0436 \u043F\u0440\u0438 \u0437\u0430\u0445\u043E\u0434\u0435 \u043E\u0434\u043D\u043E\u0439 \u0438\u0437 \u044D\u0442\u0438\u0445 \u043A\u0430\u0440\u0442. \u042D\u0442\u043E \u0437\u0430\u043F\u0440\u0435\u0449\u0435\u043D\u043E \u0432 \u043F\u0435\u0440\u0432\u043E\u0439 \u0432\u0437\u044F\u0442\u043A\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u0438 \u043F\u0440\u0438 \u043E\u0442\u0432\u0435\u0442\u0435 \u043D\u0430 \u0447\u0443\u0436\u043E\u0439 \u0437\u0430\u0445\u043E\u0434. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u043E\u0440\u043E\u043B\u044F \u0438\u043B\u0438 \u0434\u0430\u043C\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Shift+Enter: \u043A\u0430\u0440\u0442\u0430 \u0432\u044B\u0439\u0434\u0435\u0442 \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0441 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435\u043C.",
              "\u041C\u0430\u0440\u044C\u044F\u0436 \u0441\u0440\u0430\u0437\u0443 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043E\u0447\u043A\u0438 \u0438 \u0434\u0435\u043B\u0430\u0435\u0442 \u0441\u0432\u043E\u044E \u043C\u0430\u0441\u0442\u044C \u043A\u043E\u0437\u044B\u0440\u043D\u043E\u0439. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u043C\u0430\u0440\u044C\u044F\u0436 \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u0440\u0435\u0436\u043D\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C. \u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u043C\u0430\u0441\u0442\u0438:",
              "- \u0427\u0435\u0440\u0432\u043E\u0432\u044B\u0439 \u043C\u0430\u0440\u044C\u044F\u0436 \u2014 100 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0411\u0443\u0431\u043D\u043E\u0432\u044B\u0439 \u2014 80.",
              "- \u0422\u0440\u0435\u0444\u043E\u0432\u044B\u0439 \u2014 60.",
              "- \u041F\u0438\u043A\u043E\u0432\u044B\u0439 \u2014 40.",
              "\u041C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u043E\u0440\u043E\u043B\u044F \u0438\u043B\u0438 \u0434\u0430\u043C\u0443 \u0438 \u0431\u0435\u0437 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 Enter \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448. \u041A\u043E\u0433\u0434\u0430 \u043F\u0430\u0440\u0430 \u0440\u0430\u0437\u0434\u0435\u043B\u0435\u043D\u0430, \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u044D\u0442\u043E\u0442 \u043C\u0430\u0440\u044C\u044F\u0436 \u0443\u0436\u0435 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u0441\u044F."),
            rule_section(:scoring, "\u0420\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0440\u0430\u0437\u0434\u0430\u0447\u0438",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438 \u043A\u0430\u0440\u0442 \u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043C\u0430\u0440\u044C\u044F\u0436\u0435\u0439. \u0412 \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u043F\u0430\u0440\u0442\u0438\u0438 \u043E\u043D\u0438 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0442\u0430\u043A:",
              "- \u0412\u044B\u043F\u043E\u043B\u043D\u0438\u0432\u0448\u0438\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0440\u043E\u0432\u043D\u043E \u0435\u0433\u043E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043E\u0431\u0435\u0449\u0430\u0432 150 \u0438 \u0441\u043E\u0431\u0440\u0430\u0432 170, \u0432\u044B \u0437\u0430\u043F\u0438\u0448\u0435\u0442\u0435 150.",
              "- \u0417\u0430 \u043D\u0435\u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u0432\u0441\u044F \u0435\u0433\u043E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C. \u041F\u0440\u0438 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0438 150 \u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0435 149 \u0432\u044B \u043F\u043E\u0442\u0435\u0440\u044F\u0435\u0442\u0435 150 \u043E\u0447\u043A\u043E\u0432.",
              "- \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442 \u0441\u043E\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043E\u0447\u043A\u0438 \u0441 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435\u043C \u0434\u043E \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0435\u0433\u043E \u0447\u0438\u0441\u043B\u0430, \u043A\u0440\u0430\u0442\u043D\u043E\u0433\u043E \u043F\u044F\u0442\u0438. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, 42 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u0432 40, \u0430 43 \u2014 \u0432 45.",
              "\u0417\u0430 \u043A\u0430\u0436\u0434\u044B\u0435 \u0442\u0440\u0438 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u0431\u0435\u0437 \u0435\u0434\u0438\u043D\u043E\u0433\u043E \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u043D\u043D\u043E\u0433\u043E \u043E\u0447\u043A\u0430 \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u0435\u0449\u0451 120. \u042D\u0442\u0438 \u043D\u0443\u043B\u0435\u0432\u044B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0434\u043E\u043B\u0436\u043D\u044B \u0438\u0434\u0442\u0438 \u043F\u043E\u0434\u0440\u044F\u0434. \u0421\u0447\u0451\u0442 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 S, \u0447\u0438\u0441\u043B\u043E \u043D\u0443\u043B\u0435\u0439 \u0438 \u043E\u0442\u043A\u0430\u0437\u043E\u0432 \u043E\u0442 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430 \u2014 Shift+S."),
            rule_section(:surrender, "\u041E\u0442\u043A\u0430\u0437 \u043E\u0442 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430",
              "\u041F\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0432 \u043F\u0440\u0438\u043A\u0443\u043F, \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0442\u044C \u0440\u0430\u0437\u0434\u0430\u0447\u0443. \u0420\u0435\u0448\u0438\u0442\u044C \u043D\u0443\u0436\u043D\u043E \u0434\u043E \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u043F\u0435\u0440\u0432\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443. \u041F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Tab \u043A \u043A\u043D\u043E\u043F\u043A\u0435 \u043E\u0442\u043A\u0430\u0437\u0430 \u043E\u0442 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter.",
              "\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u0437\u0430 \u0442\u0430\u043A\u043E\u0439 \u043E\u0442\u043A\u0430\u0437 \u043D\u0435 \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F. \u0421\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043F\u043E \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430, \u043D\u043E \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 60 \u043A\u0430\u0436\u0434\u044B\u0439, \u0441 \u043E\u043A\u0440\u0443\u0433\u043B\u0435\u043D\u0438\u0435\u043C \u0432\u0432\u0435\u0440\u0445 \u0434\u043E \u043A\u0440\u0430\u0442\u043D\u043E\u0433\u043E \u043F\u044F\u0442\u0438. \u041A\u0430\u0436\u0434\u044B\u0439 \u0442\u0440\u0435\u0442\u0438\u0439 \u0432\u0430\u0448 \u043E\u0442\u043A\u0430\u0437 \u0441\u0442\u043E\u0438\u0442 120 \u043E\u0447\u043A\u043E\u0432."),
            rule_section(:ending, "\u0411\u043E\u0447\u043A\u0430 \u0438 \u043F\u043E\u0431\u0435\u0434\u0430",
              "\u0415\u0441\u043B\u0438 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430 \u0432\u0430\u0448 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0434\u043E\u0441\u0442\u0438\u0433 880, \u043D\u043E \u0435\u0449\u0451 \u043D\u0435 1000, \u043E\u043D \u0444\u0438\u043A\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044F \u043D\u0430 880. \u042D\u0442\u043E \u043D\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0431\u043E\u0447\u043A\u043E\u0439. \u0412 \u0442\u0435\u0447\u0435\u043D\u0438\u0435 \u0442\u0440\u0451\u0445 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0445 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0445 \u0440\u0430\u0437\u0434\u0430\u0447 \u043D\u0443\u0436\u043D\u043E \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u0442\u043E\u0440\u0433\u0438 \u0438 \u0434\u043E\u0431\u0440\u0430\u0442\u044C \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u044E\u0449\u0438\u0435 \u043E\u0447\u043A\u0438.",
              "\u041D\u0430 \u0431\u043E\u0447\u043A\u0435 \u043F\u043E\u0431\u0435\u0434\u0443 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0432\u043E\u0439 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 120. \u0411\u043E\u043B\u0435\u0435 \u043D\u0438\u0437\u043A\u0438\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0438 \u043E\u0447\u043A\u0438 \u043F\u0440\u0438 \u0447\u0443\u0436\u043E\u043C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0435 \u0441\u0447\u0451\u0442 \u043D\u0435 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0432\u0430\u044E\u0442. \u041D\u0443\u043B\u0435\u0432\u044B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043D\u0430 \u0431\u043E\u0447\u043A\u0435 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u0448\u0442\u0440\u0430\u0444\u0435 \u0437\u0430 \u0442\u0440\u0438 \u043D\u0443\u043B\u044F.",
              "\u041F\u0440\u043E\u0432\u0430\u043B \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u0441\u0440\u0430\u0437\u0443 \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u0435\u0433\u043E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0438 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0432\u0430\u0441 \u0441 \u0431\u043E\u0447\u043A\u0438. \u0415\u0441\u043B\u0438 \u0437\u0430 \u0442\u0440\u0438 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C, \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F 120 \u043E\u0447\u043A\u043E\u0432 \u0438 \u0432\u044B \u0442\u043E\u0436\u0435 \u043F\u043E\u043A\u0438\u0434\u0430\u0435\u0442\u0435 \u0431\u043E\u0447\u043A\u0443. \u041E\u0441\u0442\u0430\u0442\u043E\u043A \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 Shift+S.",
              "\u041D\u0430 \u0431\u043E\u0447\u043A\u0435 \u043E\u0442\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C\u0441\u044F \u043E\u0442 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043D\u0435\u043B\u044C\u0437\u044F. \u041E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0447\u0443\u0436\u043E\u0439 \u043E\u0442\u043A\u0430\u0437 \u0432\u044B \u0442\u0430\u043A\u0436\u0435 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435, \u043D\u043E \u0442\u0430\u043A\u0430\u044F \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u043D\u0435 \u0440\u0430\u0441\u0445\u043E\u0434\u0443\u0435\u0442 \u0432\u0430\u0448\u0443 \u043F\u043E\u043F\u044B\u0442\u043A\u0443.",
              "\u041F\u0430\u0440\u0442\u0438\u044F \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0438 1000 \u043E\u0447\u043A\u043E\u0432 \u0438\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435. \u0411\u043E\u043B\u044C\u0448\u0438\u043C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u0438 \u0434\u043E \u043F\u043E\u043F\u0430\u0434\u0430\u043D\u0438\u044F \u043D\u0430 \u0431\u043E\u0447\u043A\u0443. \u0415\u0441\u043B\u0438 \u0446\u0435\u043B\u044C \u043E\u0434\u043D\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442\u0430 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u043C\u0438 \u0438\u0433\u0440\u043E\u043A\u0430\u043C\u0438, \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442."),
            rule_section(:variants, "\u0414\u0440\u0443\u0433\u0438\u0435 \u0441\u043E\u0441\u0442\u0430\u0432\u044B \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438",
              "\u041F\u0435\u0440\u0435\u0434 \u043F\u0430\u0440\u0442\u0438\u0435\u0439 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u0441\u043E\u0441\u0442\u0430\u0432 \u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0438\u0433\u0440\u044B. \u0422\u0440\u043E\u0435 \u0438\u0433\u0440\u0430\u044E\u0442 \u043F\u043E \u043E\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u043C \u0432\u044B\u0448\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C. \u0414\u0440\u0443\u0433\u0438\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u043C\u0435\u043D\u044F\u044E\u0442 \u0440\u0430\u0437\u0434\u0430\u0447\u0443:",
              "- \u0412\u0434\u0432\u043E\u0451\u043C \u0434\u0435\u043B\u0430\u044E\u0442 \u0434\u0432\u0430 \u043F\u0440\u0438\u043A\u0443\u043F\u0430. \u041E\u0431\u044B\u0447\u043D\u043E \u0432 \u043A\u0430\u0436\u0434\u043E\u043C \u043F\u043E \u0442\u0440\u0438 \u043A\u0430\u0440\u0442\u044B, \u0430 \u0438\u0433\u0440\u043E\u043A\u0430\u043C \u0440\u0430\u0437\u0434\u0430\u044E\u0442 \u043F\u043E \u0434\u0435\u0432\u044F\u0442\u044C. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432 \u0432\u0441\u043B\u0435\u043F\u0443\u044E \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u043F\u0440\u0438\u043A\u0443\u043F \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 Enter, \u043F\u043E\u0441\u043B\u0435 \u0447\u0435\u0433\u043E \u0435\u0433\u043E \u043A\u0430\u0440\u0442\u044B \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0431\u043E\u0438\u043C. \u0417\u0430\u0442\u0435\u043C \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0441 \u0440\u0443\u043A\u0438 \u0442\u0440\u0438 \u043A\u0430\u0440\u0442\u044B, \u0432\u044B\u0431\u0438\u0440\u0430\u044F \u043A\u0430\u0436\u0434\u0443\u044E \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 Enter, \u0430 \u043D\u0435 \u043E\u0442\u0434\u0430\u0451\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0443. \u0414\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u0430 \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F \u043E\u0442 \u0440\u0430\u0437\u0434\u0430\u0447\u0438.",
              "- \u0412\u0447\u0435\u0442\u0432\u0435\u0440\u043E\u043C \u0441\u0434\u0430\u044E\u0449\u0438\u0439 \u043E\u0442\u0434\u044B\u0445\u0430\u0435\u0442, \u0430 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0442\u0440\u043E\u0435 \u0438\u0433\u0440\u0430\u044E\u0442 \u043E\u0431\u044B\u0447\u043D\u0443\u044E \u0440\u0430\u0437\u0434\u0430\u0447\u0443. \u041E\u0442\u0434\u044B\u0445\u0430\u044E\u0449\u0438\u0439 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043D\u0435 \u0440\u0430\u0441\u0445\u043E\u0434\u0443\u0435\u0442 \u043F\u043E\u043F\u044B\u0442\u043A\u0443 \u043D\u0430 \u0431\u043E\u0447\u043A\u0435. \u0412 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0440\u0430\u0437\u0434\u0430\u0447\u0435 \u043E\u0442\u0434\u044B\u0445\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A.",
              "- \u041A\u043E\u043C\u0430\u043D\u0434\u043D\u044B\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D \u043D\u0430 \u0434\u0432\u0435 \u043F\u0430\u0440\u044B \u0441 \u043E\u0431\u0449\u0438\u043C \u0441\u0447\u0451\u0442\u043E\u043C \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u0432.",
              "\u0412 \u0438\u0433\u0440\u0435 \u0432\u0434\u0432\u043E\u0451\u043C \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0440\u0438\u043A\u0443\u043F\u044B \u043F\u043E \u0434\u0432\u0435 \u043A\u0430\u0440\u0442\u044B. \u0422\u043E\u0433\u0434\u0430 \u0443 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0434\u0435\u0441\u044F\u0442\u044C \u043A\u0430\u0440\u0442, \u0430 \u043F\u043E\u0441\u043B\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u043F\u0440\u0438\u043A\u0443\u043F\u0430 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0434\u0432\u0435.",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u0434\u0432\u043E\u0451\u043C \u043E\u0447\u043A\u0438 \u043D\u0435\u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u043F\u0440\u0438\u043A\u0443\u043F\u0430 \u0438 \u043E\u0442\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0445 \u043A\u0430\u0440\u0442 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438. \u042D\u0442\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u2014 \u0442\u043E\u0433\u0434\u0430 \u044D\u0442\u0438 \u043E\u0447\u043A\u0438 \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043D\u0438\u043A\u0442\u043E.",
              "\u0426\u0435\u043B\u044C \u043F\u043E \u043E\u0447\u043A\u0430\u043C \u0442\u043E\u0436\u0435 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C. \u0411\u043E\u0447\u043A\u0430 \u0432\u0441\u0435\u0433\u0434\u0430 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0437\u0430 120 \u043E\u0447\u043A\u043E\u0432 \u0434\u043E \u0446\u0435\u043B\u0438; \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0435\u0451 \u043F\u0440\u0430\u0432\u0438\u043B\u0430 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043F\u0440\u0435\u0436\u043D\u0438\u043C\u0438."),
            rule_section(:teams, "\u0418\u0433\u0440\u0430 \u043F\u0430\u0440\u0430\u043C\u0438",
              "\u0412 \u043F\u0430\u0440\u0435 \u0432\u044B \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0432\u043C\u0435\u0441\u0442\u0435. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0435\u0441\u043B\u0438 \u0432\u044B \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u0442\u043E\u0440\u0433\u0438 \u0441 \u043E\u0431\u0435\u0449\u0430\u043D\u0438\u0435\u043C 150, \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438 \u0438 \u0432\u0430\u0448\u0438\u0445 \u0432\u0437\u044F\u0442\u043E\u043A, \u0438 \u0432\u0437\u044F\u0442\u043E\u043A \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u0430. \u0412\u0434\u0432\u043E\u0451\u043C \u043D\u0443\u0436\u043D\u043E \u0441\u043E\u0431\u0440\u0430\u0442\u044C \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 150.",
              "\u041A\u0430\u0436\u0434\u043E\u043C\u0443 \u0440\u0430\u0437\u0434\u0430\u044E\u0442 \u043F\u044F\u0442\u044C \u043A\u0430\u0440\u0442, \u0432 \u043F\u0440\u0438\u043A\u0443\u043F\u0435 \u0447\u0435\u0442\u044B\u0440\u0435. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432 \u0431\u0435\u0440\u0451\u0442 \u043F\u0440\u0438\u043A\u0443\u043F \u0438 \u043E\u0442\u0434\u0430\u0451\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0438\u0437 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0442\u0440\u043E\u0438\u0445, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u0430.",
              "\u041E\u0447\u043A\u0438 \u043A\u0430\u0440\u0442 \u0438 \u043C\u0430\u0440\u044C\u044F\u0436\u0435\u0439 \u043E\u0431\u0449\u0438\u0435, \u043D\u043E \u043A\u0430\u0436\u0434\u044B\u0439 \u0438\u0433\u0440\u0430\u0435\u0442 \u0441\u0432\u043E\u0438\u043C\u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438 \u043F\u043E \u043E\u0431\u044B\u0447\u043D\u044B\u043C \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C: \u0432 \u043C\u0430\u0441\u0442\u044C, \u0430 \u043F\u0440\u0438 \u0435\u0451 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u2014 \u043A\u043E\u0437\u044B\u0440\u0435\u043C, \u0435\u0441\u043B\u0438 \u043E\u043D \u0435\u0441\u0442\u044C. \u042D\u0442\u043E \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0438 \u0442\u043E\u0433\u0434\u0430, \u043A\u043E\u0433\u0434\u0430 \u043F\u0430\u0440\u0442\u043D\u0451\u0440 \u0443\u0436\u0435 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0437\u044F\u0442\u043A\u0443.",
              "\u0423 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442, \u043E\u0431\u0449\u0430\u044F \u0431\u043E\u0447\u043A\u0430 \u0438 \u043E\u0431\u0449\u0438\u0439 \u0437\u0430\u043F\u0430\u0441 \u043F\u043E\u043F\u044B\u0442\u043E\u043A \u043D\u0430 \u043D\u0435\u0439. \u041D\u0443\u043B\u0438 \u0438 \u043E\u0442\u043A\u0430\u0437\u044B \u0442\u0430\u043A\u0436\u0435 \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043F\u0430\u0440\u0443. \u041F\u043E\u0434\u0441\u0447\u0451\u0442 \u0442\u0430\u043A\u043E\u0439 \u0436\u0435, \u043A\u0430\u043A \u0432 \u043B\u0438\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u0435, \u043D\u043E \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A\u043E \u0432\u0441\u0435\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u0435."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0443, \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0435\u043C\u0443\u044E \u0438\u043B\u0438 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0435\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443.",
              "Enter: \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0432\u044B\u0431\u043E\u0440; \u043D\u0430 \u043A\u0430\u0440\u0442\u0435 \u2014 \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0435\u0451 \u0438\u043B\u0438 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043C\u0430\u0440\u044C\u044F\u0436\u0430.",
              "Shift+Enter: \u0441\u0440\u0430\u0437\u0443 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0439 \u043C\u0430\u0440\u044C\u044F\u0436; \u0435\u0441\u043B\u0438 \u0435\u0433\u043E \u043D\u0435\u0442, \u043A\u0430\u0440\u0442\u0430 \u043D\u0435 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F.",
              "B: \u043F\u043E\u0441\u043B\u0435 \u043E\u0431\u043C\u0435\u043D\u0430 \u0438 \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442; \u0432 \u0434\u0440\u0443\u0433\u043E\u0435 \u0432\u0440\u0435\u043C\u044F \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0438.",
              "H: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443.",
              "C: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0432\u043E \u0432\u0437\u044F\u0442\u043A\u0435.",
              "Ctrl+C: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u0432\u043E \u0432\u0437\u044F\u0442\u043A\u0435.",
              "F: \u0443\u0437\u043D\u0430\u0442\u044C \u043A\u043E\u0437\u044B\u0440\u044C.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0447\u0451\u0442 \u0438 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0430 \u0431\u043E\u0447\u043A\u0435.",
              "Shift+S: \u0443\u0437\u043D\u0430\u0442\u044C \u043D\u0443\u043B\u0438, \u043E\u0442\u043A\u0430\u0437\u044B \u0438 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043F\u043E\u043F\u044B\u0442\u043A\u0438 \u043D\u0430 \u0431\u043E\u0447\u043A\u0435.",
              "Z: \u043D\u0430\u0439\u0442\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443; \u043F\u0440\u0438 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u043C\u0430\u0440\u044C\u044F\u0436\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D.",
              "Shift+Z: \u043D\u0430\u0439\u0442\u0438 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u043A\u0430\u0440\u0442\u0443; \u043F\u0440\u0438 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u043C\u0430\u0440\u044C\u044F\u0436\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434.",
              "Shift+C: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u043C\u0430\u0441\u0442\u044F\u043C; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+H: \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043F\u043E \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0443; \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043D\u0430 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439.",
              "Shift+M: \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043A\u0430\u0440\u0442.")
          ]
        end
      end
